"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["91709"],{96705(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>u,frontMatter:()=>d,contentTitle:()=>c,toc:()=>h,assets:()=>p});var a=JSON.parse('{"id":"nhcx/v1/api/payment-notice/endpoints/payment-notice-internal-v1-paymentnotice-request","title":"Payment notice request (internal) (adapter)","description":"Internal twin of /v1/paymentnotice/request (operationId paymentNoticeRequestPostInternal) with the same JWEPayload body and response set. Exposed for the NHCX a","source":"@site/docs/nhcx/v1/api/payment-notice/endpoints/payment-notice-internal-v1-paymentnotice-request.mdx","sourceDirName":"nhcx/v1/api/payment-notice/endpoints","slug":"/nhcx/v1/api/payment-notice/endpoints/payment-notice-internal-v1-paymentnotice-request","permalink":"/docs/pr-10/docs/nhcx/v1/api/payment-notice/endpoints/payment-notice-internal-v1-paymentnotice-request","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Payment notice request (internal) (adapter)","sidebar_label":"Payment notice request (internal) (adapter)","sidebar_class_name":"api-method api-method--post","description":"Internal twin of /v1/paymentnotice/request (operationId paymentNoticeRequestPostInternal) with the same JWEPayload body and response set. Exposed for the NHCX a","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","verification":"unverified","source":"nhcx-payment-notice.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Payment notice acknowledgement","permalink":"/docs/pr-10/docs/nhcx/v1/api/payment-notice/endpoints/payment-notice-v1-paymentnotice-on-request"},"next":{"title":"Payment notice acknowledgement (internal) (adapter)","permalink":"/docs/pr-10/docs/nhcx/v1/api/payment-notice/endpoints/payment-notice-internal-v1-paymentnotice-on-request"}}'),i=n(62540),o=n(43023),r=n(70862),s=JSON.parse('{"id":"payment_notice_internal_v1_paymentnotice_request","module":"Payment notice","moduleId":"payment-notice","kind":"operation","method":"POST","path":"/internal/v1/paymentnotice/request","server":"https://apisbx.abdm.gov.in/hcx","servers":[{"url":"https://apisbx.abdm.gov.in/hcx","description":"Sandbox, NHCX exchange."},{"url":"https://apisprod.nha.gov.in/hcx","description":"Production."}],"summary":"Payment notice request (internal) (adapter)","description":"Internal twin of /v1/paymentnotice/request (operationId paymentNoticeRequestPostInternal) with the same JWEPayload body and response set. Exposed for the NHCX adapter deployment rather than for direct integration.\\n\\n### Business purpose\\n\\nThe paymentnotice service publishes its request operation twice, at /v1 and at /internal/v1, with identical descriptions, request bodies and response sets. Only the operationId differs, by an Internal suffix. The /internal prefix is the route the NHCX adapter sits on: a participant running the adapter alongside its own system calls the internal path, and the adapter handles the encryption, headers and gateway hop. A participant integrating directly against NHCX calls the public path and does that work itself. No separate business purpose is documented for the internal route beyond that.\\n\\n### When to use\\n\\nUse it only when you are running the NHCX adapter and it is configured to serve this path; otherwise call /v1/paymentnotice/request. Everything else is unchanged: the same JWEPayload body, the same x-hcx-* protected header, the same workflow discriminators and the same asynchronous callback. The specs do not document what makes the internal variant different beyond the operationId, so treat it as a mirror of the public path and confirm with NHCX onboarding before pointing production at it.\\n\\n### Preconditions\\n\\nIdentical to /v1/paymentnotice/request. Nothing additional is documented for the internal route, beyond an adapter deployment that actually serves the /internal prefix.\\n\\n### Postconditions\\n\\nNHCX returns HTTP 202 Accepted with a StatusSuccessResponse acknowledgement (entity_type payment) and forwards the bundle asynchronously to the provider\'s registered callback endpoint, which must acknowledge with 202 within 30 seconds. The provider then sends its own acknowledgement Task (status completed, output paymentack, workflow 17) on /v1/paymentnotice/on_request; only after that acknowledgement is the payment lifecycle considered closed. Protocol failures at the provider come back as a ProtocolResponse with x-hcx-error_details. Statuses 400, 404 and 500 carry the same schema.\\n\\n### Common mistakes\\n\\n- Assuming a different body or different semantics for the internal route; the spec gives it the same JWEPayload body and the same responses.\\n- Calling it without an adapter deployment behind it and then chasing a 404.\\n- Every pitfall of the public path applies unchanged.\\n\\n### Best practices\\n\\n- Default to /v1/paymentnotice/request and keep the internal path as a configuration option only.\\n- Share one client implementation across both paths, so header hygiene, encryption and correlation handling cannot diverge between them.\\n- Record which variant carried each correlation ID, for support conversations.\\n\\n### Related scenario\\n\\nA vendor reading the paymentnotice OpenAPI document sees paymentNoticeRequestPostInternal sitting beside its public twin and asks which one to build against. The answer is the public path, unless NHCX onboarding has given them an adapter deployment, in which case the adapter takes the bundle unencrypted on the internal path and does the JWE and the gateway hop for them. The end-to-end flow is identical either way.\\n\\n### Specification\\n\\nChapter [Payment notice and acknowledgement](/docs/nhcx/v1/reference/fhir/payment-notice-and-acknowledgement) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"},{"name":"x-hcx-sender_code","required":true,"description":"Your participant code. Mandatory on the envelope.","example":"1518@hcx","type":"string"},{"name":"x-hcx-recipient_code","required":true,"description":"The recipient\'s. For a provider, the processor code from the policy lookup. Mandatory on the envelope.","example":"1000004446@hcx","type":"string"},{"name":"x-hcx-api_call_id","required":true,"description":"Fresh on every message, including responses. Mandatory on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-request_id","required":false,"description":"One per originating request. The Open Protocol page marks it Mandatory; the Technical Specifications page marks it Optional. Optional on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-correlation_id","required":true,"description":"The thread. See the rule below. Mandatory on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-workflow_id","required":false,"description":"Which step, or which case. See the two readings below. Optional on the envelope.","example":"30","type":"string"},{"name":"x-hcx-timestamp","required":true,"description":"See the format note below. Mandatory on the envelope.","example":"<iso timestamp>","type":"string"},{"name":"x-hcx-status","required":true,"description":"Where this message stands. Values below. Mandatory on the envelope.","example":"request.initiated","type":"string"},{"name":"x-hcx-ben-abha-id","required":true,"description":"The beneficiary\'s ABHA number. Mandatory on every exchange, including those with no beneficiary in the payload. Mandatory on the envelope.","example":"91711234567890","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"payload","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"payload":"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOi4uLn0.encrypted_key.iv.ciphertext.tag"},"responses":[{"status":"202","description":"NHCX returns HTTP 202 Accepted with a StatusSuccessResponse acknowledgement (entity_type payment) and forwards the bundle asynchronously to the provider\'s registered callback endpoint, which must acknowledge with 202 within 30 seconds.","example":{"timestamp":"27/02/2026 15:36:09:004","api_call_id":"c3d2e1f0-a9b8-4c7d-9e6f-5a4b3c2d1e0f","correlation_id":"c3d2e1f0-a9b8-4c7d-9e6f-5a4b3c2d1e0f","result":{"sender_code":"1518@hcx","recipient_code":"1000004446@hcx","entity_type":"payment","protocol_status":"request.queued"},"error":{"code":"","message":""}}}],"tag":"Adapter","tagDescription":"Exposed for the NHCX adapter deployment rather than for direct integration.","atom":null,"curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/internal/v1/paymentnotice/request \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'x-hcx-sender_code: 1518@hcx\' \\\\\\n  --header \'x-hcx-recipient_code: 1000004446@hcx\' \\\\\\n  --header \'x-hcx-api_call_id: <uuid>\' \\\\\\n  --header \'x-hcx-request_id: <uuid>\' \\\\\\n  --header \'x-hcx-correlation_id: <uuid>\' \\\\\\n  --header \'x-hcx-workflow_id: 30\' \\\\\\n  --header \'x-hcx-timestamp: <iso timestamp>\' \\\\\\n  --header \'x-hcx-status: request.initiated\' \\\\\\n  --header \'x-hcx-ben-abha-id: 91711234567890\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOi4uLn0.encrypted_key.iv.ciphertext.tag\\"\\n}\'"}');let d={title:"Payment notice request (internal) (adapter)",sidebar_label:"Payment notice request (internal) (adapter)",sidebar_class_name:"api-method api-method--post",description:"Internal twin of /v1/paymentnotice/request (operationId paymentNoticeRequestPostInternal) with the same JWEPayload body and response set. Exposed for the NHCX a",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",verification:"unverified",source:"nhcx-payment-notice.yaml",generated:!0},c,p={},h=[];function l(e){return(0,i.jsx)(r.A,{operation:s})}function u(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}}}]);